invariant zig_codegen_generate_outputs_complete_module
    // generate() outputs complete Zig module with execute function
    // Rationale: Generated code must be valid Zig
    assert true;

invariant zig_codegen_register_file_size
    // Register file always has 27 registers (r0-r25 general, r26 zero)
    // Rationale: Coptic encoding requires 27 registers
    assert true;

