        if (total_ffs(cat) > board.ffs) {
            return false;
        }
        if (total_bram18(cat) > board.bram18) {
            return false;
        }
        if (total_dsp48(cat) > board.dsp48) {
            return false;
        }
        return true;
    }

    fn luts_remaining(cat: IpCatalog, board: BoardResources) -> u32 {
        if (total_luts(cat) > board.luts) {
            return 0;
        }
        return board.luts - total_luts(cat);
    }

    fn utilization_percent(cat: IpCatalog, board: BoardResources) -> u32 {
        if (board.luts == 0) {
            return 0;
        }
        return total_luts(cat) * 100 / board.luts;
