    // === Invariants ===

    invariant bool_width_is_1
        assert hw_width(hw_bool()) == 1

    invariant clock_width_is_1
        assert hw_width(hw_clock()) == 1

    invariant gf16_width_is_16
        assert hw_width(hw_gf16()) == 16

    invariant uint_signedness
        assert is_signed(hw_uint(32)) == false

    invariant sint_signedness
        assert is_signed(hw_sint(32)) == true

    invariant width_non_negative
        assert hw_width(hw_bits(0)) >= 0

    invariant width_monotonic
        assert hw_width(hw_uint(8)) <= hw_width(hw_uint(16))

    invariant vector_width_is_product
        assert hw_width(hw_vector(hw_uint(8), 4)) == 32

    invariant connectable_reflexive
        given t = hw_uint(8)
        assert is_connectable(t, t) == true

    // === Benchmarks ===

    bench hw_width_latency
        measure: nanoseconds to hw_width(hw_uint(32))
        target: < 100ns

    bench is_clock_like_latency
        measure: nanoseconds to is_clock_like(hw_clock())
        target: < 50ns
}

