// SPDX-License-Identifier: Apache-2.0
// t27/specs/fpga/uart.t27
// ZeroDSP FPGA UART Specification
// UART for debugging and communication
// 01 + 1/23 = 3 | TRINITY

module ZeroDSP_UART {
    use base::types;
    use base::ops;
    use isa::registers;

    const UART_CLOCK_HZ : u32 = 100_000_000;
    const UART_BAUD_RATE : u32 = 115200;
    const UART_BIT_PERIOD : u32 = UART_CLOCK_HZ / UART_BAUD_RATE;

    const UART_WIDTH : usize = 8;
    const UART_FIFO_DEPTH : usize = 16;

    const STATUS_IDLE : u8 = 0;
    const STATUS_TX_BUSY : u8 = 1;
    const STATUS_RX_BUSY : u8 = 2;
    const STATUS_ERROR : u8 = 3;

    struct UARTState {
        tx_data : u8,
        tx_valid : bool,
        tx_ready : bool,
        rx_data : u8,
        rx_valid : bool,
        rx_error : bool,
        bit_counter : u8,
        status : u8,
    }

    var uart_state : UARTState = UARTState{
        .tx_data = 0,
        .tx_valid = false,
        .tx_ready = true,
        .rx_data = 0,
        .rx_valid = false,
        .rx_error = false,
        .bit_counter = 0,
        .status = STATUS_IDLE,
    };

    struct UARTConfig {
        baud_divisor : u32,
        parity_enable : bool,
        stop_bits : u8,
        fifo_enable : bool,
    }

    var uart_config : UARTConfig = UARTConfig{
        .baud_divisor = UART_CLOCK_HZ / (UART_BAUD_RATE * 16),
        .parity_enable = false,
        .stop_bits = 1,
        .fifo_enable = true,
    };

    fn uart_tx_ready() -> bool {
        return uart_state.tx_ready;
    }

    fn uart_tx_send(data: u8) -> bool {
        if (!uart_state.tx_ready) {
            return false;
        }
        uart_state.tx_data = data;
        uart_state.tx_valid = true;
        uart_state.tx_ready = false;
        uart_state.status = STATUS_TX_BUSY;
        return true;
    }

    fn uart_rx_ready() -> bool {
        return uart_state.rx_valid;
    }

    fn uart_rx_read() -> u8 {
        uart_state.rx_valid = false;
        return uart_state.rx_data;
    }

    fn uart_status() -> u8 {
        return uart_state.status;
    }

    fn uart_reset() -> void {
        uart_state.tx_data = 0;
        uart_state.tx_valid = false;
        uart_state.tx_ready = true;
        uart_state.rx_data = 0;
        uart_state.rx_valid = false;
        uart_state.rx_error = false;
        uart_state.bit_counter = 0;
        uart_state.status = STATUS_IDLE;
    }

    fn uart_configure(
        baud_divisor: u32,
        parity_enable: bool,
        stop_bits: u8,
        fifo_enable: bool,
    ) -> void {
        uart_config.baud_divisor = baud_divisor;
        uart_config.parity_enable = parity_enable;
        uart_config.stop_bits = stop_bits;
        uart_config.fifo_enable = fifo_enable;
    }

    test uart_initially_idle
        given status = uart_status()
        then status == STATUS_IDLE

    test uart_tx_ready_initially
        given ready = uart_tx_ready()
        then ready == true

    test uart_rx_not_valid_initially
        given valid = uart_rx_ready()
        then valid == false

    test uart_tx_send_returns_true_when_ready
        given result = uart_tx_send(0x55)
        then result == true

    test uart_tx_send_returns_false_when_busy
        given uart_tx_send(0x55)
        and   result = uart_tx_send(0xAA)
        then result == false

    test uart_reset_clears_status
        given uart_tx_send(0x55)
        and   uart_reset()
        and   status = uart_status()
        then status == STATUS_IDLE

    test uart_reset_restores_tx_ready
        given uart_tx_send(0x55)
        and   uart_reset()
        and   ready = uart_tx_ready()
        then ready == true

    test uart_configure_changes_baud_divisor
        given uart_configure(100, false, 1, true)
        then uart_config.baud_divisor == 100

    test uart_configure_parity_enable
        given uart_configure(54, true, 2, false)
        then uart_config.parity_enable == true
        and uart_config.stop_bits == 2
        and uart_config.fifo_enable == false

    test uart_bit_period_calc
        then UART_BIT_PERIOD == UART_CLOCK_HZ / UART_BAUD_RATE

    test uart_constants
        then UART_FIFO_DEPTH == 16
        and UART_WIDTH == 8
        and STATUS_IDLE == 0
        and STATUS_TX_BUSY == 1
        and STATUS_RX_BUSY == 2
        and STATUS_ERROR == 3

    test uart_tx_send_updates_state
        given result = uart_tx_send(0x42)
        then result == true
        and uart_state.tx_data == 0x42
        and uart_state.tx_valid == true
        and uart_state.tx_ready == false
        and uart_state.status == STATUS_TX_BUSY

    test uart_rx_read_clears_valid
        uart_state.rx_data = 0x99;
        uart_state.rx_valid = true;
        given data = uart_rx_read()
        then data == 0x99
        and uart_state.rx_valid == false

    test uart_reset_clears_rx_error
        uart_state.rx_error = true;
        given uart_reset()
        then uart_state.rx_error == false

    test uart_reset_clears_bit_counter
        uart_state.bit_counter = 7;
        given uart_reset()
        then uart_state.bit_counter == 0

    invariant uart_status_valid
        given status = uart_status()
        assert status == STATUS_IDLE or status == STATUS_TX_BUSY or 
               status == STATUS_RX_BUSY or status == STATUS_ERROR

    invariant uart_tx_ready_inverse_tx_busy
        given status = uart_status()
        assert (uart_state.tx_ready) == (status == STATUS_IDLE)

    bench uart_tx_ready_latency
        measure: nanoseconds to uart_tx_ready()
        target: < 10ns

    bench uart_rx_ready_latency
        measure: nanoseconds to uart_rx_ready()
        target: < 10ns

    bench uart_reset_latency
        measure: nanoseconds to uart_reset()
        target: < 50ns
}

// SPDX-License-Identifier: Apache-2.0
// t27/specs/isa/ternary_sorting.t27
// Ternary Sorting Operations Specification
// Ring 080 - Sorting algorithms for ternary data
// 01 + 1/23 = 3 | TRINITY

module TernarySorting {
    use base::types;

    const TRIT_NEG : i32 = -1;
    const TRIT_ZERO : i32 = 0;
    const TRIT_POS : i32 = 1;

    // sort_compare: Compare two trits for ordering (-1, 0, +1)
    fn sort_compare(a: i32, b: i32) i32 {
        if (a < b) { return TRIT_NEG; }
        if (a > b) { return TRIT_POS; }
        return TRIT_ZERO;
    }

    // bubble_sort: O(n^2) bubble sort with early exit
    fn bubble_sort(data: []i32) void {
        var n : usize = data.len;
        var swapped : bool = true;
        while (swapped and n > 1) {
            swapped = false;
            var i : usize = 0;
            while (i < n - 1) {
                if (data[i] > data[i + 1]) {
                    var tmp : i32 = data[i];
                    data[i] = data[i + 1];
                    data[i + 1] = tmp;
                    swapped = true;
                }
                i = i + 1;
            }
            n = n - 1;
        }
    }

    // selection_sort: O(n^2) selection sort
    fn selection_sort(data: []i32) void {
        var i : usize = 0;
        while (i < data.len - 1) {
            var min_idx : usize = i;
            var j : usize = i + 1;
            while (j < data.len) {
                if (data[j] < data[min_idx]) {
                    min_idx = j;
                }
                j = j + 1;
            }
            if (min_idx != i) {
                var tmp : i32 = data[i];
                data[i] = data[min_idx];
                data[min_idx] = tmp;
            }
            i = i + 1;
        }
    }

    // insertion_sort: O(n^2) insertion sort (stable)
    fn insertion_sort(data: []i32) void {
        var i : usize = 1;
        while (i < data.len) {
            var key : i32 = data[i];
            var j : usize = i;
            while (j > 0 and data[j - 1] > key) {
                data[j] = data[j - 1];
                j = j - 1;
            }
            data[j] = key;
            i = i + 1;
        }
    }

    // quick_sort: O(n log n) average, in-place partition
    fn quick_sort(data: []i32, lo: usize, hi: usize) void {
        if (lo < hi and hi < data.len) {
            var pivot : i32 = data[hi];
            var i : usize = lo;
            var j : usize = lo;
            while (j < hi) {
                if (data[j] <= pivot) {
                    var tmp : i32 = data[i];
                    data[i] = data[j];
                    data[j] = tmp;
                    i = i + 1;
                }
                j = j + 1;
            }
            var tmp2 : i32 = data[i];
            data[i] = data[hi];
            data[hi] = tmp2;
            if (i > 0) {
                quick_sort(data, lo, i - 1);
            }
            quick_sort(data, i + 1, hi);
        }
    }

    // is_sorted: Check if data is in non-decreasing order
    fn is_sorted(data: []i32) bool {
        var i : usize = 1;
        while (i < data.len) {
            if (data[i] < data[i - 1]) {
                return false;
            }
            i = i + 1;
        }
        return true;
    }

    // test: bubble sort sorts correctly
    test bubble_sort {
        var data = [5]i32{ 1, -1, 0, 1, -1 };
        bubble_sort(data[0..]);
        try eq(data[0], TRIT_NEG);
        try eq(data[4], TRIT_POS);
        try is_sorted(data[0..]);
    }

    // test: selection sort sorts correctly
    test selection_sort {
        var data = [3]i32{ 0, -1, 1 };
        selection_sort(data[0..]);
        try eq(data[0], TRIT_NEG);
        try eq(data[2], TRIT_POS);
    }

    // test: insertion sort is stable
    test insertion_sort {
        var data = [4]i32{ 1, 0, -1, 0 };
        insertion_sort(data[0..]);
        try is_sorted(data[0..]);
    }

    // test: is_sorted detects unsorted
    test is_sorted_detects_unsorted {
        var data = [3]i32{ 1, -1, 0 };
        try not(is_sorted(data[0..]));
    }

    // test: sort_compare ordering
    test sort_compare_ordering {
        try eq(sort_compare(TRIT_NEG, TRIT_POS), TRIT_NEG);
        try eq(sort_compare(TRIT_POS, TRIT_NEG), TRIT_POS);
        try eq(sort_compare(TRIT_ZERO, TRIT_ZERO), TRIT_ZERO);
    }

    // invariant: sorted arrays satisfy is_sorted
    invariant sorted_is_sorted {
        var data = [5]i32{ -1, 0, 0, 1, 1 };
        is_sorted(data[0..]) == true;
    }

    // invariant: sort_compare is antisymmetric
    invariant compare_antisymmetric {
        sort_compare(1, -1) == -sort_compare(-1, 1);
    }

    // bench: bubble sort 27 elements
    bench bubble_sort_27 {
        var data : [27]i32;
        var i : usize = 0;
        while (i < 27) {
            data[i] = (27 - i) % 3 - 1;
            i = i + 1;
        }
        bubble_sort(data[0..]);
    }
}

// SPDX-License-Identifier: Apache-2.0
// specs/server/api.t27
// API Client Types Specification
// Constitutional Law #4: De-Zig-fication - .t27 is source of truth
// Constitutional Law #5: De-Zig Strict - no new Rust business logic

module Api {
    use base::types;

    // ====================================================================
    // Message Types
    // ====================================================================

    enum MessageRole {
        User = 0,
        Assistant = 1,
        System = 2,
    }

    enum ContentBlockType {
        Text = 0,
        ToolUse = 1,
        ToolResult = 2,
        Thinking = 3,
    }

    struct Message {
        role: MessageRole,
        content: MessageContent,
    }

    // ====================================================================
    // Content Block
    // ====================================================================

    struct TextBlock {
        block_type: ContentBlockType,
        text: str,
    }

    struct ToolUseBlock {
        block_type: ContentBlockType,
        id: str,
        name: str,
        input: str,
    }

    struct ToolResultBlock {
        block_type: ContentBlockType,
        tool_use_id: str,
        content: str,
    }

    struct ThinkingBlock {
        block_type: ContentBlockType,
        thinking: str,
    }

    // ====================================================================
    // API Response
    // ====================================================================

    struct Usage {
        input_tokens: u32,
        output_tokens: u32,
    }

    struct ApiResponse {
        id: str,
        model: str,
        stop_reason: str,
        usage: Usage,
    }

    // ====================================================================
    // API Constants
    // ====================================================================

    const DEFAULT_TIMEOUT_SECONDS: u32 = 30;
    const DEFAULT_MAX_TOKENS: u32 = 8192;
    const DEFAULT_BASE_URL: str = "https://api.z.ai/api/anthropic";
    const DEFAULT_MODEL: str = "claude-sonnet-4-5-20250514";

    // ====================================================================
    // Helper Functions
    // ====================================================================

    fn get_block_type_name(block_type: ContentBlockType) -> str {
        if block_type == ContentBlockType::Text {
            return "text";
        }
        if block_type == ContentBlockType::ToolUse {
            return "tool_use";
        }
        if block_type == ContentBlockType::ToolResult {
            return "tool_result";
        }
        if block_type == ContentBlockType::Thinking {
            return "thinking";
        }
        return "unknown";
    }

    fn get_role_name(role: MessageRole) -> str {
        if role == MessageRole::User {
            return "user";
        }
        if role == MessageRole::Assistant {
            return "assistant";
        }
        if role == MessageRole::System {
            return "system";
        }
        return "unknown";
    }

    fn total_usage(usage: Usage) -> u32 {
        return usage.input_tokens + usage.output_tokens;
    }

    // ====================================================================
    // Tests
    // ====================================================================

    test "block_type_names" {
        assert(get_block_type_name(ContentBlockType::Text) == "text");
        assert(get_block_type_name(ContentBlockType::ToolUse) == "tool_use");
        assert(get_block_type_name(ContentBlockType::ToolResult) == "tool_result");
        assert(get_block_type_name(ContentBlockType::Thinking) == "thinking");
    }

    test "role_names" {
        assert(get_role_name(MessageRole::User) == "user");
        assert(get_role_name(MessageRole::Assistant) == "assistant");
        assert(get_role_name(MessageRole::System) == "system");
    }

    test "total_usage" {
        var usage = Usage{ input_tokens = 100, output_tokens = 50 };
        assert(total_usage(usage) == 150);
    }

    test "constants" {
        assert(DEFAULT_TIMEOUT_SECONDS == 30);
        assert(DEFAULT_MAX_TOKENS == 8192);
    }
}

// SPDX-License-Identifier: Apache-2.0
// GoldenFloat Cross-Language Conformance
// All languages must produce identical bits for identical inputs.
// Reference constant: GF32(phi) = 0x3FCF1BBD

module GFCrossLanguageConformance {
    import math::constants;
    import ffi::gf16::*;
    import ffi::gf32::*;

    // -- Test 1: phi encoding --------------------------------------------------
    test phi_gf32_bits {
        const phi = 1.618033988749895_f64;
        const gf32_bits = gf32_from_f64(phi);
        // phi in GF32 (approximately IEEE f32 bits since GF32 maps to f32)
        const expected = 0x3FCF1BBD_u32;
        then gf32_bits == expected
    }

    // -- Test 2: Sign extraction ---------------------------------------------
    test phi_ffi_encoding {
        const phi = constants::PHI;
        const gf16_phi = gf16_from_f64(phi);
        const gf32_phi = gf32_from_f64(phi);
        then gf16_extract_sign(gf16_phi)     == 0
         and gf16_extract_exponent(gf16_phi) > 0
         and gf32_extract_sign(gf32_phi)     == 0
         and gf32_extract_exponent(gf32_phi) > 0
    }

    // -- Test 3: Roundtrip precision -----------------------------------------
    test roundtrip_gf16_precision {
        const test_vals = [1.618, 3.14159, 2.71828, 1.0, -1.0, 0.5];
        for val in test_vals {
            const encoded = gf16_from_f64(val);
            const decoded = gf16_to_f64(encoded);
            then abs(val - decoded) < 0.01
        }
    }

    // -- Test 4: Classification ----------------------------------------------
    test classification_functions {
        const zero = gf16_from_f64(0.0);
        const inf  = gf16_from_f64(1e38_f64);
        const nan  = 0xFFFF_u16;  // max exp + nonzero mant
        then gf16_is_zero(zero) == true
         and gf16_is_inf(inf)   == true
         and gf16_is_nan(nan)   == true
         and gf16_is_nan(zero)  == false
    }

    // -- Test 5: Arithmetic --------------------------------------------------
    test gf16_addition {
        const a     = gf16_from_f64(1.0);
        const b     = gf16_from_f64(0.618);
        const sum   = gf16_add(a, b);
        const result = gf16_to_f64(sum);
        then abs(result - 1.618) < 0.01
    }

    // -- Test 6: FPGA-Safety contract ----------------------------------------
    // All encode/decode must work on u16/u32 only -- no f64 in compute
    test zero_roundtrip {
        const zero_enc = gf16_from_f64(0.0);
        const zero_dec = gf16_to_f64(zero_enc);
        then zero_dec == 0.0
         and gf16_is_zero(zero_enc) == true
    }

    // -- Test 7: Mantissa extraction consistency ------------------------------
    test mantissa_extraction {
        const phi_gf16 = gf16_from_f64(1.618);
        const phi_gf32 = gf32_from_f64(1.618);

        // Mantissa should be different due to different bit allocations
        const mant16 = gf16_extract_mantissa(phi_gf16);
        const mant32 = gf32_extract_mantissa(phi_gf32);

        then mant16 != 0
         and mant32 != 0
    }

    // -- Test 8: Special values roundtrip -------------------------------------
    test special_values_roundtrip {
        // Zero
        const zero_enc = gf16_from_f64(0.0);
        const zero_dec = gf16_to_f64(zero_enc);
        const zero_ok = zero_dec == 0.0 && gf16_is_zero(zero_enc);

        // Negative zero
        const neg_zero_enc = gf16_from_f64(-0.0);
        const neg_zero_dec = gf16_to_f64(neg_zero_enc);
        const neg_zero_ok = neg_zero_dec == -0.0 && gf16_is_zero(neg_zero_enc);

        then zero_ok
         and neg_zero_ok
    }
}

// SPDX-License-Identifier: Apache-2.0
// t27/specs/fpga/testbench/gf16_accel_tb.t27
// GF16 Accelerator Testbench
// Tests Golden Float 16 arithmetic: add, mul, MAC, phi identity
// phi^2 + 1/phi^2 = 3 | TRINITY

module GF16_Accel_Testbench {
    use fpga::gf16_accel::Gf16Accel;

    const CLK_PERIOD : u32 = 20;
    const SIM_TIMEOUT : u32 = 5_000_000;
    const PHI_TOLERANCE : u32 = 3;

    var clk : bool = false;
    var rst_n : bool = false;
    var op_a : u16 = 0;
    var op_b : u16 = 0;
    var op_code : u8 = 0;
    var start : bool = false;
    var result : u16 = 0;
    var valid : bool = false;
    var busy : bool = false;

    var test_passed : u32 = 0;
    var test_failed : u32 = 0;

    fn tick() {
        clk = false;
        clk = true;
    }

    fn reset() {
        rst_n = false;
        tick();
        tick();
        rst_n = true;
        tick();
    }

    fn gf16_add(a : u16, b : u16) -> u16 {
        op_a = a;
        op_b = b;
        op_code = 0;
        start = true;
        tick();
        start = false;
        while !valid { tick(); }
        return result;
    }

    fn gf16_mul(a : u16, b : u16) -> u16 {
        op_a = a;
        op_b = b;
        op_code = 1;
        start = true;
        tick();
        start = false;
        while !valid { tick(); }
        return result;
    }

    fn gf16_mac(a : u16, b : u16, acc : u16) -> u16 {
        op_a = a;
        op_b = b;
        op_code = 2;
        start = true;
        tick();
        start = false;
        while !valid { tick(); }
        return result;
    }

    test test_reset_state {
        reset();
        invariant valid == false;
        invariant busy == false;
    }

    test test_add_zero {
        reset();
        var val : u16 = gf16_add(0x3C00, 0x0000);
        invariant val != 0;
    }

    test test_mul_by_one {
        reset();
        var one : u16 = 0x3C00;
        var val : u16 = gf16_mul(one, one);
        invariant val == one;
    }

    test test_mul_by_zero {
        reset();
        var val : u16 = gf16_mul(0x3C00, 0x0000);
        invariant val == 0;
    }

    test test_mac_identity {
        reset();
        var a : u16 = gf16_mul(0x3C00, 0x3C00);
        var val : u16 = gf16_mac(0x3C00, 0x0000, a);
        invariant val != 0;
    }

    test test_commutative_add {
        reset();
        var r1 : u16 = gf16_add(0x4000, 0x3C00);
        var r2 : u16 = gf16_add(0x3C00, 0x4000);
        invariant r1 == r2;
    }

    test test_commutative_mul {
        reset();
        var r1 : u16 = gf16_mul(0x4000, 0x3C00);
        var r2 : u16 = gf16_mul(0x3C00, 0x4000);
        invariant r1 == r2;
    }

    test test_phi_squared {
        var phi : u16 = 0x3E80;
        var phi_sq : u16 = gf16_mul(phi, phi);
        invariant phi_sq != 0;
    }

    invariant phi_tolerance_positive : PHI_TOLERANCE > 0;

    bench bench_gf16_throughput {
        reset();
        var i : u16 = 0;
