}
invariant gf16_bits_total
    assert GF16_BITS == 16
    try std.testing.expect(GF16_SIGN_BIT == GF16_BITS - 1);

invariant gf16_exp_mant_sum
    assert GF16_EXP_BITS + GF16_MANT_BITS == GF16_BITS - 1

invariant posit16_bits_total
    assert POSIT16_BITS == 16

invariant posit16_es_value
    assert POSIT16_ES == 1

invariant posit16_regime_mant_sum
    assert POSIT16_REGIME_BITS + POSIT16_MANT_BITS == POSIT16_BITS - POSIT16_ES - 1

invariant gf16_from_bits_roundtrip
    given bits = 0x5678
    assert gf16_to_bits(gf16_from_bits(bits)) == bits

invariant posit16_from_bits_roundtrip
    given bits = 0x4000
    assert posit16_to_bits(posit16_from_bits(bits)) == bits

invariant gf16_zero_exp_zero_mant_zero
    given gf = Gf16{.sign = 0, .exp = 0, .mant = 0}
