invariant conversion_config_init_clamp_enabled
    given config = conversion_config_init()
    assert config.clamp_overflow == true

invariant gf16_to_posit16_zero_preserves
    given gf = Gf16{.sign = 0, .exp = 0, .mant = 0}
    try std.testing.expect(p = gf16_to_posit16(gf));
    try std.testing.expect(posit16_is_zero(p) and not posit16_get_sign(p));

invariant gf16_to_posit16_infinity_to_naR
    given gf = Gf16{.sign = 0, .exp = 0x3F, .mant = 0}
