        PUSH = 79,
        POP = 80,
        LOAD = 81,
        STORE = 82,
        SHL = 83,
        SHR = 84,
        AndOp = 85,
        OrOp = 86,
        XorOp = 87,
        NOT = 88,
        NEG = 89,
        SQRT = 90,
        TANH = 91,
        TRAP = 92,

        // TDD-Inside-Spec high-level keywords (spec-style)
        Spec = 93,
