    // =====================================================================
    // Node types -- enum of all AST node types
    // =====================================================================

    pub const NodeType = enum(u8) {
        // Program structure
        Program = 0,
        DataSection = 1,
        CodeSection = 2,

        // Constants
        ConstDef = 10,

        // Data declarations
        DWord = 20,
        DSpace = 21,
        DTrit = 22,

        // Instructions
        Mov = 30,
        Jz = 31,
        Jnz = 32,
        Jmp = 33,
        Mul = 34,
        Add = 35,
        Sub = 36,
        Bind = 37,
        Bundle = 38,
        Halt = 39,

        // Operands
        Reg = 40,
        Imm = 41,
        Label = 42,
        Mem = 43,

        // TDD-Inside-Spec blocks (assembly-style)
        Test = 50,
        Invariant = 51,
        Bench = 52,
        TestCase = 53,
        InvariantDecl = 54,
        BenchDecl = 55,

        // TDD-Inside-Spec high-level structures (spec-style)
        SpecDecl = 60,           // spec keyword/module header
        RuleBlock = 61,          // rule block
        GivenClause = 62,        // given clause in test
        WhenClause = 63,         // when clause in test
        ThenClause = 64,         // then clause in test
        AndClause = 65,          // and clause in test
        ExpectClause = 66,       // expect clause in rule
