    // =====================================================================
    // AST Node -- base structure for all nodes
    // =====================================================================

    pub const ASTNode = struct {
        node_type: NodeType,
        line: u32,
        column: u32,
        source_file: []const u8,
    };

    // =====================================================================
    // Program -- root node
    // =====================================================================

    pub const Program = struct {
        node: ASTNode,
        spec_decl: ?SpecDecl,          // spec declaration (high-level)
        constants: []ConstDef,
        data_section: DataSection,
        code_section: CodeSection,
        test_section: ?TestSection,     // .test section
        invariant_section: ?InvariantSection,  // .invariant section
        bench_section: ?BenchSection,   // .bench section
        exports: [][]const u8,          // Exported symbols
        imports: [][]const u8,          // Imported modules
