    // =====================================================================
    // Constants and Data
    // =====================================================================

    pub const ConstDef = struct {
        node: ASTNode,
        name: []const u8,
        value: i64,                    // Immediate value
    };

    pub const DataSection = struct {
        node: ASTNode,
        declarations: []DataDecl,
    };

    pub const DataDecl = struct {
        node: ASTNode,
        size: u8,                      // 1 = trit, 8 = dword, etc.
        initial_value: i64,
        label: []const u8,
    };

    // =====================================================================
    // Code and Instructions
    // =====================================================================

    pub const CodeSection = struct {
        node: ASTNode,
        instructions: []Instruction,
        labels: std.StringHashMap(u32),  // Label -> instruction index
    };

    pub const Instruction = struct {
        node: ASTNode,
        opcode: Opcode,
