    pub const Operand = struct {
        node: ASTNode,
        operand_type: OperandType,
    };

    pub const OperandType = enum(u8) {
        Register = 0,
        Immediate = 1,
        LabelRef = 2,
        Memory = 3,
    };

    pub const RegOperand = struct {
        node: ASTNode,
        reg_num: u8,                   // 0-25 for general, 26 for zero
    };

    pub const ImmOperand = struct {
        node: ASTNode,
        value: i64,
    };

    pub const LabelOperand = struct {
        node: ASTNode,
        label_name: []const u8,
    };

    pub const MemOperand = struct {
        node: ASTNode,
        base_reg: u8,
        offset: i16,
    };

    // =====================================================================
    // TDD-Inside-Spec structures
    // =====================================================================

    // TestCase -- a single test case from .test section
    // Format: ; test_name ; Verify: description ; Expected: expected outcome
    pub const TestCase = struct {
        node: ASTNode,
        name: []const u8,               // test identifier (snake_case)
        verify_description: []const u8, // "Verify:" description
        expected_outcome: []const u8,  // "Expected:" description
        setup_description: []const u8, // "Setup:" description (optional)
        rationale: ?[]const u8,        // Additional rationale (optional)
    };

    // InvariantDecl -- an invariant from .invariant section
    // Format: ; invariant_name ; Rationale: explanation
    pub const InvariantDecl = struct {
        node: ASTNode,
        name: []const u8,               // invariant identifier (snake_case)
        formal_statement: []const u8,  // The invariant statement (may be logic)
        rationale: []const u8,          // "Rationale:" explanation
    };

    // BenchDecl -- a benchmark from .bench section
    // Format: ; bench_name ; Measure: what to measure ; Target: target value
    pub const BenchDecl = struct {
        node: ASTNode,
        name: []const u8,               // benchmark identifier (snake_case)
        measure_description: []const u8, // "Measure:" description
        target: ?[]const u8,            // "Target:" description (optional)
        units: []const u8,              // Units of measurement (e.g., "cycles", "ns", "ops/sec")
    };

    // =====================================================================
    // TDD-Inside-Spec high-level structures (spec-style)
    // =====================================================================

    // SpecDecl -- spec module header declaration
    // Format: spec <name>
    pub const SpecDecl = struct {
        node: ASTNode,
        name: []const u8,               // spec/module identifier
        constants: []ConstDef,         // spec-level constants
        test_blocks: []TestBlock,      // test blocks in spec
        invariants: []AssertStmt,       // invariants in spec
        rules: []RuleDecl,             // rules in spec
    };

    // TestBlock -- a complete test with given/when/then clauses
    // Format: test <name> { given ... when ... then ... }
    pub const TestBlock = struct {
        node: ASTNode,
        name: []const u8,               // test identifier (snake_case)
        given_clauses: []GivenClause,   // setup clauses
        when_clauses: []WhenClause,    // action clauses
        then_clauses: []ThenClause,    // assertion clauses
    };

    pub const GivenClause = struct {
        node: ASTNode,
        variable: []const u8,           // variable name
        expression: []const u8,         // setup expression
    };

    pub const WhenClause = struct {
        node: ASTNode,
        variable: []const u8,           // variable name
        expression: []const u8,         // action expression
    };

    pub const ThenClause = struct {
        node: ASTNode,
        expression: []const u8,         // assertion expression
    };

    pub const AndClause = struct {
        node: ASTNode,
        expression: []const u8,         // continuation expression
        clause_type: []const u8,        // "given", "when", or "then"
    };

    pub const AssertStmt = struct {
        node: ASTNode,
        expression: []const u8,         // assertion expression
    };

    pub const RuleDecl = struct {
        node: ASTNode,
        name: []const u8,               // rule identifier (snake_case)
        expect_clauses: []ExpectClause, // expectation clauses
    };

    pub const ExpectClause = struct {
        node: ASTNode,
        expression: []const u8,         // expectation expression
    };

    // =====================================================================
    // Type information for codegen
    // =====================================================================

    pub const TypeInfo = struct {
        name: []const u8,
        size_bits: u8,
        is_signed: bool,
    };

    // =====================================================================
    // Symbol table
    // =====================================================================

    pub const Symbol = struct {
        name: []const u8,
        node: ASTNode,
        scope: []const u8,
        is_exported: bool,
        is_defined: bool,
    };

    pub const SymbolTable = struct {
        parent: ?*SymbolTable,
        symbols: std.StringHashMap(Symbol),
        children: []SymbolTable,

        pub fn new(parent: ?*SymbolTable) SymbolTable {
            return SymbolTable{
                .parent = parent,
                .symbols = std.StringHashMap(Symbol).init(std.heap.page_allocator),
                .children = &[_]SymbolTable{},
            };
        }

        pub fn add(self: *SymbolTable, sym: Symbol) !bool {
            try self.symbols.put(sym.name, sym);
            return true;
        }

        pub fn lookup(self: *SymbolTable, name: []const u8) ?Symbol {
            if (self.symbols.get(name)) |s| {
                return s;
            }
            if (self.parent) |p| {
                return p.lookup(name);
            }
            return null;
        }
    };

    // =====================================================================
    // Compiler context -- passed through all compilation stages
    // =====================================================================

    pub const CompilerContext = struct {
        ast_root: Program,
        symbol_table: SymbolTable,
        errors: []CompilerError,
        warnings: []CompilerWarning,
        current_phase: CompilationPhase,
    };

    pub const CompilationPhase = enum(u8) {
        Parsing = 0,
        SemanticAnalysis = 1,
        CodeGeneration = 2,
        Optimization = 3,
    };

    pub const CompilerError = struct {
        message: []const u8,
        line: u32,
        column: u32,
        source_file: []const u8,
        phase: CompilationPhase,
    };

    pub const CompilerWarning = struct {
        message: []const u8,
        line: u32,
        column: u32,
        source_file: []const u8,
    };

    pub const SymbolExport = struct {
        name: []const u8,
        type_info: TypeInfo,
    };

    pub fn CompilerContext_add_error(self: *CompilerContext, msg: []const u8, line: u32, column: u32) !void {
        try self.errors.append(CompilerError{
            .message = msg,
            .line = line,
            .column = column,
            .source_file = self.ast_root.node.source_file,
            .phase = self.current_phase,
        });
    }

    pub fn CompilerContext_add_warning(self: *CompilerContext, msg: []const u8, line: u32, column: u32) !void {
        try self.warnings.append(CompilerWarning{
            .message = msg,
            .line = line,
            .column = column,
            .source_file = self.ast_root.node.source_file,
        });
    }

    pub fn CompilerContext_has_errors(self: *CompilerContext) bool {
        return self.errors.len > 0;
    }

    pub fn CompilerContext_error_count(self: *CompilerContext) u32 {
        return @intCast(self.errors.len);
    }

    pub fn Program_export_symbols(self: *Program) ![]SymbolExport {
        // Traverse symbol table and collect exported symbols
        // Returns list of {name, type, size} for external linkage
        _ = self;
        return &[_]SymbolExport{};
    }
}

